/**
 * FreeWire Phase 14 - 캔버스 확장 모듈
 *
 * 포함 기능:
 *   1. Minimap     — 캔버스 전체를 축소해서 보여주는 네비게이터
 *   2. MultiSelect — Shift+클릭, 드래그 박스 다중 선택
 *   3. UndoRedo    — GraphHistory 기반 Undo/Redo 어댑터
 *   4. Shortcuts   — 키보드 단축키 라우터
 */

'use strict';

const { GraphHistory } = typeof require !== 'undefined'
  ? require('../core/graph-history')
  : { GraphHistory: class { push(){}; undo(){ return null; } redo(){ return null; } get canUndo(){ return false; } get canRedo(){ return false; } } };

// ─── 1. Minimap ─────────────────────────────────────────────────

/**
 * 캔버스의 모든 노드를 지정된 크기의 축소 맵으로 렌더링.
 * DOM에 의존하지 않고 순수 계산으로 좌표 변환을 제공.
 */
class Minimap {
  /**
   * @param {object} options
   * @param {number} options.width   미니맵 픽셀 너비 (기본 180)
   * @param {number} options.height  미니맵 픽셀 높이 (기본 120)
   * @param {number} options.padding 내부 여백 (기본 8)
   */
  constructor({ width = 180, height = 120, padding = 8 } = {}) {
    this.width   = width;
    this.height  = height;
    this.padding = padding;
  }

  /**
   * 노드 목록 → 미니맵 좌표 배열로 변환
   * @param {Array<{id, x, y, w, h}>} nodes
   * @returns {{ nodes: Array<{id, mx, my, mw, mh}>, viewport: {scale, offsetX, offsetY} }}
   */
  project(nodes) {
    if (!nodes || nodes.length === 0) {
      return { nodes: [], viewport: { scale: 1, offsetX: 0, offsetY: 0 } };
    }

    // 바운딩 박스 계산
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const n of nodes) {
      const nx = n.x ?? 0, ny = n.y ?? 0;
      const nw = n.w ?? 120, nh = n.h ?? 80;
      minX = Math.min(minX, nx);
      minY = Math.min(minY, ny);
      maxX = Math.max(maxX, nx + nw);
      maxY = Math.max(maxY, ny + nh);
    }

    const contentW = maxX - minX || 1;
    const contentH = maxY - minY || 1;
    const availW   = this.width  - this.padding * 2;
    const availH   = this.height - this.padding * 2;
    const scale    = Math.min(availW / contentW, availH / contentH);

    // 중앙 정렬 오프셋
    const scaledW  = contentW * scale;
    const scaledH  = contentH * scale;
    const offsetX  = this.padding + (availW - scaledW) / 2;
    const offsetY  = this.padding + (availH - scaledH) / 2;

    const projected = nodes.map(n => ({
      id:  n.id,
      mx:  Math.round((( n.x ?? 0) - minX) * scale + offsetX),
      my:  Math.round((( n.y ?? 0) - minY) * scale + offsetY),
      mw:  Math.max(4, Math.round((n.w ?? 120) * scale)),
      mh:  Math.max(3, Math.round((n.h ?? 80)  * scale)),
      selected: n.selected ?? false,
    }));

    return { nodes: projected, viewport: { scale, offsetX, offsetY, minX, minY } };
  }

  /**
   * 미니맵 좌표 → 캔버스 월드 좌표 역변환
   * @param {number} mx  미니맵 X
   * @param {number} my  미니맵 Y
   * @param {object} viewport  project()가 반환한 viewport
   * @returns {{ worldX, worldY }}
   */
  toWorld(mx, my, viewport) {
    const { scale, offsetX, offsetY, minX = 0, minY = 0 } = viewport;
    return {
      worldX: (mx - offsetX) / scale + minX,
      worldY: (my - offsetY) / scale + minY,
    };
  }
}

// ─── 2. MultiSelect ─────────────────────────────────────────────

/**
 * 드래그 박스 + Shift+클릭 기반 다중 노드 선택 관리자
 */
class MultiSelect {
  constructor() {
    /** @type {Set<string>} 현재 선택된 노드 ID 집합 */
    this.selected = new Set();
    this._box = null;   // 드래그 박스: {x0,y0,x1,y1}
  }

  /** 선택 전체 해제 */
  clear() {
    this.selected.clear();
  }

  /**
   * 노드 하나 토글 (Shift+클릭)
   * @param {string} id
   */
  toggle(id) {
    if (this.selected.has(id)) this.selected.delete(id);
    else                        this.selected.add(id);
  }

  /**
   * 단일 선택 (일반 클릭 — 기존 선택 해제)
   * @param {string} id
   */
  selectOne(id) {
    this.selected.clear();
    this.selected.add(id);
  }

  /**
   * 드래그 박스 시작
   * @param {number} x  캔버스 월드 X
   * @param {number} y  캔버스 월드 Y
   */
  beginBox(x, y) {
    this._box = { x0: x, y0: y, x1: x, y1: y };
  }

  /**
   * 드래그 박스 업데이트
   * @param {number} x
   * @param {number} y
   */
  updateBox(x, y) {
    if (this._box) { this._box.x1 = x; this._box.y1 = y; }
  }

  /**
   * 드래그 박스 종료 — 박스 안에 있는 노드 선택
   * @param {Array<{id, x, y, w, h}>} nodes
   * @param {boolean} additive  true면 기존 선택에 추가
   * @returns {Set<string>} 새로 선택된 노드 ID 집합
   */
  endBox(nodes, additive = false) {
    if (!this._box) return this.selected;
    const { x0, y0, x1, y1 } = this._box;
    this._box = null;

    const rx = Math.min(x0, x1), ry = Math.min(y0, y1);
    const rw = Math.abs(x1 - x0), rh = Math.abs(y1 - y0);

    if (!additive) this.selected.clear();

    for (const n of nodes) {
      if (this._intersects(n.x ?? 0, n.y ?? 0, n.w ?? 120, n.h ?? 80, rx, ry, rw, rh)) {
        this.selected.add(n.id);
      }
    }
    return this.selected;
  }

  /** 현재 드래그 박스 좌표 반환 (정규화) */
  getBox() {
    if (!this._box) return null;
    const { x0, y0, x1, y1 } = this._box;
    return {
      x: Math.min(x0, x1), y: Math.min(y0, y1),
      w: Math.abs(x1 - x0), h: Math.abs(y1 - y0),
    };
  }

  /** 두 AABB 교차 여부 */
  _intersects(ax, ay, aw, ah, bx, by, bw, bh) {
    return ax < bx + bw && ax + aw > bx &&
           ay < by + bh && ay + ah > by;
  }

  /** 선택된 모든 노드를 delta 만큼 이동한 새 위치 계산 */
  moveSelected(nodes, dx, dy) {
    const result = [];
    for (const n of nodes) {
      if (this.selected.has(n.id)) {
        result.push({ id: n.id, x: (n.x ?? 0) + dx, y: (n.y ?? 0) + dy });
      }
    }
    return result;
  }

  get count() { return this.selected.size; }
  has(id)     { return this.selected.has(id); }
}

// ─── 3. UndoRedo ────────────────────────────────────────────────

/**
 * GraphHistory를 에디터에 연결하는 어댑터.
 * 스냅샷 저장/복원 인터페이스 제공.
 */
class UndoRedo {
  /**
   * @param {number} maxSize  최대 스냅샷 수 (기본 50)
   */
  constructor(maxSize = 50) {
    this._history = new GraphHistory(maxSize);
  }

  /**
   * 현재 그래프 상태를 스냅샷으로 저장
   * @param {object} graphSnapshot  직렬화된 그래프 JSON
   */
  snapshot(graphSnapshot) {
    this._history.push(graphSnapshot);
  }

  /**
   * Undo — 이전 상태 반환
   * @returns {object|null} 복원할 그래프 JSON, 없으면 null
   */
  undo() {
    return this._history.undo();
  }

  /**
   * Redo — 앞으로 이동
   * @returns {object|null} 복원할 그래프 JSON, 없으면 null
   */
  redo() {
    return this._history.redo();
  }

  get canUndo() { return this._history.canUndo; }
  get canRedo() { return this._history.canRedo; }
  get size()    { return this._history.size; }

  /** 히스토리 전체 초기화 */
  clear() {
    this._history.clear();
  }
}

// ─── 4. Shortcuts ───────────────────────────────────────────────

/**
 * 키보드 단축키 라우터.
 * DOM에 의존하지 않고 { key, ctrl, shift, alt } 객체로 매칭.
 */
class Shortcuts {
  constructor() {
    /** @type {Array<{key, ctrl, shift, alt, handler}>} */
    this._bindings = [];
  }

  /**
   * 단축키 등록
   * @param {string}   key      e.key 값 (대소문자 무관)
   * @param {object}   mods     { ctrl?, shift?, alt? }
   * @param {Function} handler  실행할 함수
   */
  bind(key, mods, handler) {
    this._bindings.push({
      key:   key.toLowerCase(),
      ctrl:  !!mods.ctrl,
      shift: !!mods.shift,
      alt:   !!mods.alt,
      handler,
    });
  }

  /**
   * 키 이벤트 처리
   * @param {{ key, ctrlKey, shiftKey, altKey }} e  KeyboardEvent 또는 동등 객체
   * @returns {boolean} 처리됐으면 true
   */
  handle(e) {
    const k = (e.key || '').toLowerCase();
    for (const b of this._bindings) {
      if (b.key   !== k)          continue;
      if (b.ctrl  !== !!e.ctrlKey)  continue;
      if (b.shift !== !!e.shiftKey) continue;
      if (b.alt   !== !!e.altKey)   continue;
      b.handler(e);
      return true;
    }
    return false;
  }

  /** 특정 키+모디파이어 조합의 핸들러 수 반환 */
  countBindings(key, mods = {}) {
    const k = key.toLowerCase();
    return this._bindings.filter(b =>
      b.key === k &&
      b.ctrl  === !!mods.ctrl &&
      b.shift === !!mods.shift &&
      b.alt   === !!mods.alt
    ).length;
  }

  /** 전체 바인딩 해제 */
  clear() {
    this._bindings = [];
  }
}

// ─── 기본 단축키 세트 생성 ──────────────────────────────────────

/**
 * FreeWire 표준 단축키 세트를 등록하고 반환
 * @param {object} handlers 각 액션 핸들러 맵
 *   handlers.undo()
 *   handlers.redo()
 *   handlers.deleteSelected()
 *   handlers.selectAll()
 *   handlers.escape()
 *   handlers.duplicate()
 * @returns {Shortcuts}
 */
function createDefaultShortcuts(handlers = {}) {
  const s = new Shortcuts();
  const noop = () => {};

  s.bind('z',      { ctrl: true  },            handlers.undo          || noop);
  s.bind('z',      { ctrl: true, shift: true }, handlers.redo          || noop);
  s.bind('y',      { ctrl: true  },            handlers.redo          || noop);
  s.bind('delete', {},                          handlers.deleteSelected || noop);
  s.bind('backspace', {},                       handlers.deleteSelected || noop);
  s.bind('a',      { ctrl: true  },            handlers.selectAll     || noop);
  s.bind('escape', {},                          handlers.escape        || noop);
  s.bind('d',      { ctrl: true  },            handlers.duplicate     || noop);

  return s;
}

// ─── 공개 API ──────────────────────────────────────────────────

module.exports = { Minimap, MultiSelect, UndoRedo, Shortcuts, createDefaultShortcuts };

