/**
 * FreeWire Phase 14 - 캔버스 확장 모듈 테스트
 * Minimap / MultiSelect / UndoRedo / Shortcuts
 */

'use strict';

const path = require('path');
const { Minimap, MultiSelect, UndoRedo, Shortcuts, createDefaultShortcuts } =
  require(path.join(__dirname, '../ui/canvas-extras'));

let passed = 0, failed = 0;
const errors = [];

function test(name, fn) {
  try { fn(); console.log(`  ✅ ${name}`); passed++; }
  catch (e) { console.log(`  ❌ ${name}: ${e.message}`); errors.push({ name, error: e.message }); failed++; }
}
function assert(cond, msg)     { if (!cond) throw new Error(msg || '조건 실패'); }
function assertEqual(a, b, msg){ if (a !== b) throw new Error(msg || `${JSON.stringify(a)} !== ${JSON.stringify(b)}`); }
function assertClose(a, b, tol = 1, msg) {
  if (Math.abs(a - b) > tol) throw new Error(msg || `${a} ≈ ${b} 아님 (허용 ±${tol})`);
}

console.log('\n📦 Phase 14: 캔버스 확장 (Minimap / MultiSelect / UndoRedo / Shortcuts)\n');

// ── 1. Minimap ────────────────────────────────────────────────
console.log('1. Minimap');

const mm = new Minimap({ width: 180, height: 120, padding: 8 });

test('빈 노드 → 빈 결과', () => {
  const r = mm.project([]);
  assertEqual(r.nodes.length, 0);
});

test('단일 노드 → 중앙 배치', () => {
  const r = mm.project([{ id: 'a', x: 0, y: 0, w: 100, h: 80 }]);
  assertEqual(r.nodes.length, 1);
  assert(r.nodes[0].mx >= 8 && r.nodes[0].mx <= 172, 'X 범위 초과');
  assert(r.nodes[0].my >= 8 && r.nodes[0].my <= 112, 'Y 범위 초과');
});

test('두 노드 → 두 엔트리 반환', () => {
  const r = mm.project([
    { id: 'a', x: 0,   y: 0,   w: 100, h: 80 },
    { id: 'b', x: 300, y: 200, w: 100, h: 80 },
  ]);
  assertEqual(r.nodes.length, 2);
});

test('오른쪽 노드가 더 큰 mx', () => {
  const r = mm.project([
    { id: 'a', x: 0,   y: 0, w: 100, h: 80 },
    { id: 'b', x: 500, y: 0, w: 100, h: 80 },
  ]);
  assert(r.nodes[1].mx > r.nodes[0].mx, '오른쪽 노드 mx가 더 커야 함');
});

test('아래쪽 노드가 더 큰 my', () => {
  const r = mm.project([
    { id: 'a', x: 0, y: 0,   w: 100, h: 80 },
    { id: 'b', x: 0, y: 400, w: 100, h: 80 },
  ]);
  assert(r.nodes[1].my > r.nodes[0].my, '아래쪽 노드 my가 더 커야 함');
});

test('미니맵 좌표가 경계 내', () => {
  const nodes = [
    { id: 'a', x: -500, y: -200, w: 120, h: 80 },
    { id: 'b', x: 800,  y: 600,  w: 120, h: 80 },
    { id: 'c', x: 200,  y: 100,  w: 120, h: 80 },
  ];
  const r = mm.project(nodes);
  for (const n of r.nodes) {
    assert(n.mx >= 0 && n.mx <= mm.width,  `mx ${n.mx} 범위 초과`);
    assert(n.my >= 0 && n.my <= mm.height, `my ${n.my} 범위 초과`);
  }
});

test('viewport.scale이 양수', () => {
  const r = mm.project([{ id: 'a', x: 0, y: 0, w: 100, h: 80 }]);
  assert(r.viewport.scale > 0, 'scale > 0');
});

test('toWorld 역변환 — 미니맵 중점이 월드 중점 근처', () => {
  const nodes = [{ id: 'a', x: 100, y: 100, w: 200, h: 100 }];
  const r = mm.project(nodes);
  const n = r.nodes[0];
  // 노드 중심 좌표 역변환
  const centerMx = n.mx + n.mw / 2;
  const centerMy = n.my + n.mh / 2;
  const { worldX, worldY } = mm.toWorld(centerMx, centerMy, r.viewport);
  assertClose(worldX, 200, 5, `worldX ${worldX} ≈ 200`);
  assertClose(worldY, 150, 5, `worldY ${worldY} ≈ 150`);
});

test('selected 노드 플래그 전달', () => {
  const r = mm.project([
    { id: 'a', x: 0, y: 0, w: 100, h: 80, selected: true },
    { id: 'b', x: 200, y: 0, w: 100, h: 80, selected: false },
  ]);
  assertEqual(r.nodes[0].selected, true);
  assertEqual(r.nodes[1].selected, false);
});

test('x/y 없는 노드는 0,0으로 처리', () => {
  const r = mm.project([{ id: 'a' }]);
  assertEqual(r.nodes.length, 1);
});

// ── 2. MultiSelect ───────────────────────────────────────────
console.log('\n2. MultiSelect');

test('초기 선택 없음', () => {
  const ms = new MultiSelect();
  assertEqual(ms.count, 0);
});

test('selectOne 후 count=1', () => {
  const ms = new MultiSelect();
  ms.selectOne('a');
  assertEqual(ms.count, 1);
  assert(ms.has('a'));
});

test('selectOne은 기존 선택 해제', () => {
  const ms = new MultiSelect();
  ms.selectOne('a');
  ms.selectOne('b');
  assertEqual(ms.count, 1);
  assert(!ms.has('a'));
  assert(ms.has('b'));
});

test('toggle 추가', () => {
  const ms = new MultiSelect();
  ms.toggle('a');
  ms.toggle('b');
  assertEqual(ms.count, 2);
});

test('toggle 제거', () => {
  const ms = new MultiSelect();
  ms.toggle('a');
  ms.toggle('a');
  assertEqual(ms.count, 0);
});

test('clear 후 count=0', () => {
  const ms = new MultiSelect();
  ms.selectOne('a');
  ms.toggle('b');
  ms.clear();
  assertEqual(ms.count, 0);
});

test('드래그 박스 — 범위 내 노드 선택', () => {
  const ms = new MultiSelect();
  const nodes = [
    { id: 'a', x: 50, y: 50, w: 100, h: 80 },
    { id: 'b', x: 500, y: 500, w: 100, h: 80 },
  ];
  ms.beginBox(0, 0);
  ms.updateBox(200, 200);
  ms.endBox(nodes);
  assert(ms.has('a'),  'a 선택돼야 함');
  assert(!ms.has('b'), 'b 선택 안돼야 함');
});

test('드래그 박스 역방향(우→좌, 하→상)도 동작', () => {
  const ms = new MultiSelect();
  const nodes = [{ id: 'a', x: 50, y: 50, w: 100, h: 80 }];
  ms.beginBox(200, 200);
  ms.updateBox(0, 0);
  ms.endBox(nodes);
  assert(ms.has('a'));
});

test('박스 종료 전 getBox() 반환', () => {
  const ms = new MultiSelect();
  ms.beginBox(10, 20);
  ms.updateBox(110, 120);
  const box = ms.getBox();
  assert(box !== null);
  assertEqual(box.w, 100);
  assertEqual(box.h, 100);
});

test('endBox 후 getBox() null', () => {
  const ms = new MultiSelect();
  ms.beginBox(0, 0);
  ms.endBox([]);
  assertEqual(ms.getBox(), null);
});

test('additive 모드 — 기존 선택 유지', () => {
  const ms = new MultiSelect();
  ms.selectOne('existing');
  ms.beginBox(0, 0);
  ms.updateBox(200, 200);
  ms.endBox([{ id: 'new', x: 50, y: 50, w: 100, h: 80 }], true);
  assert(ms.has('existing'), '기존 선택 유지');
  assert(ms.has('new'),      '신규 선택 추가');
});

test('moveSelected — delta 적용', () => {
  const ms = new MultiSelect();
  ms.toggle('a');
  const nodes = [
    { id: 'a', x: 100, y: 100 },
    { id: 'b', x: 200, y: 200 },
  ];
  const moved = ms.moveSelected(nodes, 50, -30);
  assertEqual(moved.length, 1);
  assertEqual(moved[0].x, 150);
  assertEqual(moved[0].y,  70);
});

// ── 3. UndoRedo ──────────────────────────────────────────────
console.log('\n3. UndoRedo');

test('초기 상태 canUndo=false, canRedo=false', () => {
  const ur = new UndoRedo();
  assert(!ur.canUndo);
  assert(!ur.canRedo);
});

test('snapshot 후 canUndo=true', () => {
  const ur = new UndoRedo();
  ur.snapshot({ nodes: [], edges: [] });
  assert(ur.canUndo);
});

test('undo 후 이전 상태 반환', () => {
  const ur = new UndoRedo();
  const s1 = { nodes: [{ id: 'a' }], edges: [] };
  const s2 = { nodes: [{ id: 'a' }, { id: 'b' }], edges: [] };
  ur.snapshot(s1);
  ur.snapshot(s2);
  const prev = ur.undo();
  assertEqual(prev.nodes.length, 1);
});

test('undo 후 canRedo=true', () => {
  const ur = new UndoRedo();
  ur.snapshot({ nodes: [], edges: [] });
  ur.snapshot({ nodes: [{ id: 'a' }], edges: [] });
  ur.undo();
  assert(ur.canRedo);
});

test('redo 후 앞 상태 복원', () => {
  const ur = new UndoRedo();
  ur.snapshot({ nodes: [], edges: [] });
  ur.snapshot({ nodes: [{ id: 'a' }], edges: [] });
  ur.undo();
  const next = ur.redo();
  assertEqual(next.nodes.length, 1);
});

test('snapshot 이후 redo 스택 초기화', () => {
  const ur = new UndoRedo();
  ur.snapshot({ nodes: [], edges: [] });
  ur.snapshot({ nodes: [{ id: 'a' }], edges: [] });
  ur.undo();
  ur.snapshot({ nodes: [{ id: 'b' }], edges: [] });
  assert(!ur.canRedo, 'redo 불가여야 함');
});

test('빈 상태에서 undo() null', () => {
  const ur = new UndoRedo();
  assertEqual(ur.undo(), null);
});

test('size 증가', () => {
  const ur = new UndoRedo();
  ur.snapshot({ nodes: [] });
  ur.snapshot({ nodes: [{ id: 'a' }] });
  assertEqual(ur.size, 2);
});

test('maxSize 제한', () => {
  const ur = new UndoRedo(3);
  ur.snapshot({ nodes: [{ id: '1' }] });
  ur.snapshot({ nodes: [{ id: '2' }] });
  ur.snapshot({ nodes: [{ id: '3' }] });
  ur.snapshot({ nodes: [{ id: '4' }] });
  assert(ur.size <= 3, `size ${ur.size} <= 3`);
});

test('clear 후 canUndo=false', () => {
  const ur = new UndoRedo();
  ur.snapshot({ nodes: [] });
  ur.clear();
  assert(!ur.canUndo);
});

// ── 4. Shortcuts ─────────────────────────────────────────────
console.log('\n4. Shortcuts');

test('등록한 단축키 실행', () => {
  const s = new Shortcuts();
  let called = false;
  s.bind('z', { ctrl: true }, () => { called = true; });
  s.handle({ key: 'z', ctrlKey: true, shiftKey: false, altKey: false });
  assert(called);
});

test('모디파이어 다르면 실행 안됨', () => {
  const s = new Shortcuts();
  let called = false;
  s.bind('z', { ctrl: true }, () => { called = true; });
  s.handle({ key: 'z', ctrlKey: false, shiftKey: false, altKey: false });
  assert(!called);
});

test('handle이 true 반환 (처리됨)', () => {
  const s = new Shortcuts();
  s.bind('delete', {}, () => {});
  const result = s.handle({ key: 'delete', ctrlKey: false, shiftKey: false, altKey: false });
  assertEqual(result, true);
});

test('매칭 없으면 false 반환', () => {
  const s = new Shortcuts();
  const result = s.handle({ key: 'x', ctrlKey: false, shiftKey: false, altKey: false });
  assertEqual(result, false);
});

test('대소문자 무관', () => {
  const s = new Shortcuts();
  let called = false;
  s.bind('Z', { ctrl: true }, () => { called = true; });
  s.handle({ key: 'z', ctrlKey: true, shiftKey: false, altKey: false });
  assert(called);
});

test('Ctrl+Shift+Z (Redo) 구분', () => {
  const s = new Shortcuts();
  let undoCalled = false, redoCalled = false;
  s.bind('z', { ctrl: true },             () => { undoCalled = true; });
  s.bind('z', { ctrl: true, shift: true }, () => { redoCalled = true; });
  s.handle({ key: 'z', ctrlKey: true, shiftKey: true,  altKey: false });
  assert(!undoCalled, 'undo 실행 안됨');
  assert(redoCalled,  'redo 실행');
});

test('countBindings 정확', () => {
  const s = new Shortcuts();
  s.bind('a', { ctrl: true }, () => {});
  s.bind('a', { ctrl: true }, () => {});
  assertEqual(s.countBindings('a', { ctrl: true }), 2);
});

test('clear 후 단축키 동작 안함', () => {
  const s = new Shortcuts();
  let called = false;
  s.bind('delete', {}, () => { called = true; });
  s.clear();
  s.handle({ key: 'delete', ctrlKey: false, shiftKey: false, altKey: false });
  assert(!called);
});

// ── 5. createDefaultShortcuts ────────────────────────────────
console.log('\n5. createDefaultShortcuts()');

test('기본 단축키 세트 생성', () => {
  const calls = {};
  const s = createDefaultShortcuts({
    undo:          () => { calls.undo = true; },
    redo:          () => { calls.redo = true; },
    deleteSelected:() => { calls.del  = true; },
    selectAll:     () => { calls.all  = true; },
    escape:        () => { calls.esc  = true; },
    duplicate:     () => { calls.dup  = true; },
  });

  s.handle({ key: 'z',         ctrlKey: true,  shiftKey: false, altKey: false });
  s.handle({ key: 'z',         ctrlKey: true,  shiftKey: true,  altKey: false });
  s.handle({ key: 'delete',    ctrlKey: false, shiftKey: false, altKey: false });
  s.handle({ key: 'a',         ctrlKey: true,  shiftKey: false, altKey: false });
  s.handle({ key: 'escape',    ctrlKey: false, shiftKey: false, altKey: false });
  s.handle({ key: 'd',         ctrlKey: true,  shiftKey: false, altKey: false });

  assert(calls.undo, 'undo 호출');
  assert(calls.redo, 'redo 호출');
  assert(calls.del,  'delete 호출');
  assert(calls.all,  'selectAll 호출');
  assert(calls.esc,  'escape 호출');
  assert(calls.dup,  'duplicate 호출');
});

test('Ctrl+Y도 redo 동작', () => {
  let called = false;
  const s = createDefaultShortcuts({ redo: () => { called = true; } });
  s.handle({ key: 'y', ctrlKey: true, shiftKey: false, altKey: false });
  assert(called);
});

test('Backspace도 delete 동작', () => {
  let called = false;
  const s = createDefaultShortcuts({ deleteSelected: () => { called = true; } });
  s.handle({ key: 'backspace', ctrlKey: false, shiftKey: false, altKey: false });
  assert(called);
});

// ── 결과 ─────────────────────────────────────────────────────
console.log(`\n결과: ${passed} passed, ${failed} failed / ${passed + failed} total`);
if (errors.length > 0) {
  console.log('\n실패 목록:');
  errors.forEach(e => console.log(`  ❌ ${e.name}: ${e.error}`));
}
process.exit(failed > 0 ? 1 : 0);

