console.log('1. Minimap');

const mm = new Minimap({ width: 180, height: 120, padding: 8 });

test('빈 노드 → 빈 결과', () => {
  const r = mm.project([]);
  assertEqual(r.nodes.length, 0);
});

test('단일 노드 → 중앙 배치', () => {
  const r = mm.project([{ id: 'a', x: 0, y: 0, w: 100, h: 80 }]);
  assertEqual(r.nodes.length, 1);
  assert(r.nodes[0].mx >= 8 && r.nodes[0].mx <= 172, 'X 범위 초과');
  assert(r.nodes[0].my >= 8 && r.nodes[0].my <= 112, 'Y 범위 초과');
});

test('두 노드 → 두 엔트리 반환', () => {
  const r = mm.project([
    { id: 'a', x: 0,   y: 0,   w: 100, h: 80 },
    { id: 'b', x: 300, y: 200, w: 100, h: 80 },
  ]);
  assertEqual(r.nodes.length, 2);
});

test('오른쪽 노드가 더 큰 mx', () => {
  const r = mm.project([
    { id: 'a', x: 0,   y: 0, w: 100, h: 80 },
    { id: 'b', x: 500, y: 0, w: 100, h: 80 },
  ]);
  assert(r.nodes[1].mx > r.nodes[0].mx, '오른쪽 노드 mx가 더 커야 함');
});

test('아래쪽 노드가 더 큰 my', () => {
  const r = mm.project([
    { id: 'a', x: 0, y: 0,   w: 100, h: 80 },
    { id: 'b', x: 0, y: 400, w: 100, h: 80 },
  ]);
  assert(r.nodes[1].my > r.nodes[0].my, '아래쪽 노드 my가 더 커야 함');
});

test('미니맵 좌표가 경계 내', () => {
  const nodes = [
    { id: 'a', x: -500, y: -200, w: 120, h: 80 },
    { id: 'b', x: 800,  y: 600,  w: 120, h: 80 },
    { id: 'c', x: 200,  y: 100,  w: 120, h: 80 },
  ];
  const r = mm.project(nodes);
  for (const n of r.nodes) {
    assert(n.mx >= 0 && n.mx <= mm.width,  `mx ${n.mx} 범위 초과`);
    assert(n.my >= 0 && n.my <= mm.height, `my ${n.my} 범위 초과`);
  }
});

test('viewport.scale이 양수', () => {
