console.log('\n2. MultiSelect');

test('초기 선택 없음', () => {
  const ms = new MultiSelect();
  assertEqual(ms.count, 0);
});

test('selectOne 후 count=1', () => {
  const ms = new MultiSelect();
  ms.selectOne('a');
  assertEqual(ms.count, 1);
  assert(ms.has('a'));
});

test('selectOne은 기존 선택 해제', () => {
  const ms = new MultiSelect();
  ms.selectOne('a');
  ms.selectOne('b');
  assertEqual(ms.count, 1);
  assert(!ms.has('a'));
  assert(ms.has('b'));
});

test('toggle 추가', () => {
  const ms = new MultiSelect();
  ms.toggle('a');
  ms.toggle('b');
  assertEqual(ms.count, 2);
});

test('toggle 제거', () => {
  const ms = new MultiSelect();
  ms.toggle('a');
  ms.toggle('a');
  assertEqual(ms.count, 0);
});

test('clear 후 count=0', () => {
  const ms = new MultiSelect();
  ms.selectOne('a');
  ms.toggle('b');
  ms.clear();
  assertEqual(ms.count, 0);
});

test('드래그 박스 — 범위 내 노드 선택', () => {
  const ms = new MultiSelect();
  const nodes = [
    { id: 'a', x: 50, y: 50, w: 100, h: 80 },
    { id: 'b', x: 500, y: 500, w: 100, h: 80 },
  ];
  ms.beginBox(0, 0);
  ms.updateBox(200, 200);
  ms.endBox(nodes);
  assert(ms.has('a'),  'a 선택돼야 함');
  assert(!ms.has('b'), 'b 선택 안돼야 함');
});

test('드래그 박스 역방향(우→좌, 하→상)도 동작', () => {
  const ms = new MultiSelect();
  const nodes = [{ id: 'a', x: 50, y: 50, w: 100, h: 80 }];
  ms.beginBox(200, 200);
  ms.updateBox(0, 0);
  ms.endBox(nodes);
  assert(ms.has('a'));
});

test('박스 종료 전 getBox() 반환', () => {
  const ms = new MultiSelect();
  ms.beginBox(10, 20);
  ms.updateBox(110, 120);
  const box = ms.getBox();
  assert(box !== null);
  assertEqual(box.w, 100);
  assertEqual(box.h, 100);
});

test('endBox 후 getBox() null', () => {
  const ms = new MultiSelect();
  ms.beginBox(0, 0);
  ms.endBox([]);
  assertEqual(ms.getBox(), null);
});

test('additive 모드 — 기존 선택 유지', () => {
  const ms = new MultiSelect();
  ms.selectOne('existing');
  ms.beginBox(0, 0);
  ms.updateBox(200, 200);
