  assert(ms.has('existing'), '기존 선택 유지');
  assert(ms.has('new'),      '신규 선택 추가');
});

test('moveSelected — delta 적용', () => {
  const ms = new MultiSelect();
  ms.toggle('a');
  const nodes = [
    { id: 'a', x: 100, y: 100 },
    { id: 'b', x: 200, y: 200 },
  ];
  const moved = ms.moveSelected(nodes, 50, -30);
  assertEqual(moved.length, 1);
  assertEqual(moved[0].x, 150);
  assertEqual(moved[0].y,  70);
});

// ── 3. UndoRedo ──────────────────────────────────────────────
console.log('\n3. UndoRedo');

test('초기 상태 canUndo=false, canRedo=false', () => {
  const ur = new UndoRedo();
  assert(!ur.canUndo);
  assert(!ur.canRedo);
});

test('snapshot 후 canUndo=true', () => {
  const ur = new UndoRedo();
  ur.snapshot({ nodes: [], edges: [] });
  assert(ur.canUndo);
});

test('undo 후 이전 상태 반환', () => {
  const ur = new UndoRedo();
  const s1 = { nodes: [{ id: 'a' }], edges: [] };
  const s2 = { nodes: [{ id: 'a' }, { id: 'b' }], edges: [] };
  ur.snapshot(s1);
  ur.snapshot(s2);
  const prev = ur.undo();
  assertEqual(prev.nodes.length, 1);
});

test('undo 후 canRedo=true', () => {
  const ur = new UndoRedo();
  ur.snapshot({ nodes: [], edges: [] });
  ur.snapshot({ nodes: [{ id: 'a' }], edges: [] });
  ur.undo();
  assert(ur.canRedo);
});

test('redo 후 앞 상태 복원', () => {
  const ur = new UndoRedo();
  ur.snapshot({ nodes: [], edges: [] });
  ur.snapshot({ nodes: [{ id: 'a' }], edges: [] });
  ur.undo();
  const next = ur.redo();
  assertEqual(next.nodes.length, 1);
});

test('snapshot 이후 redo 스택 초기화', () => {
  const ur = new UndoRedo();
  ur.snapshot({ nodes: [], edges: [] });
  ur.snapshot({ nodes: [{ id: 'a' }], edges: [] });
  ur.undo();
  ur.snapshot({ nodes: [{ id: 'b' }], edges: [] });
  assert(!ur.canRedo, 'redo 불가여야 함');
});

test('빈 상태에서 undo() null', () => {
  const ur = new UndoRedo();
  assertEqual(ur.undo(), null);
});

test('size 증가', () => {
  const ur = new UndoRedo();
  ur.snapshot({ nodes: [] });
  ur.snapshot({ nodes: [{ id: 'a' }] });
  assertEqual(ur.size, 2);
});

test('maxSize 제한', () => {
  const ur = new UndoRedo(3);
  ur.snapshot({ nodes: [{ id: '1' }] });
  ur.snapshot({ nodes: [{ id: '2' }] });
  ur.snapshot({ nodes: [{ id: '3' }] });
  ur.snapshot({ nodes: [{ id: '4' }] });
  assert(ur.size <= 3, `size ${ur.size} <= 3`);
});

test('clear 후 canUndo=false', () => {
  const ur = new UndoRedo();
  ur.snapshot({ nodes: [] });
  ur.clear();
  assert(!ur.canUndo);
});

// ── 4. Shortcuts ─────────────────────────────────────────────
console.log('\n4. Shortcuts');

test('등록한 단축키 실행', () => {
  const s = new Shortcuts();
  let called = false;
  s.bind('z', { ctrl: true }, () => { called = true; });
  s.handle({ key: 'z', ctrlKey: true, shiftKey: false, altKey: false });
  assert(called);
});

test('모디파이어 다르면 실행 안됨', () => {
  const s = new Shortcuts();
  let called = false;
  s.bind('z', { ctrl: true }, () => { called = true; });
  s.handle({ key: 'z', ctrlKey: false, shiftKey: false, altKey: false });
  assert(!called);
});

test('handle이 true 반환 (처리됨)', () => {
  const s = new Shortcuts();
  s.bind('delete', {}, () => {});
  const result = s.handle({ key: 'delete', ctrlKey: false, shiftKey: false, altKey: false });
  assertEqual(result, true);
});

test('매칭 없으면 false 반환', () => {
  const s = new Shortcuts();
  const result = s.handle({ key: 'x', ctrlKey: false, shiftKey: false, altKey: false });
  assertEqual(result, false);
});

test('대소문자 무관', () => {
  const s = new Shortcuts();
  let called = false;
  s.bind('Z', { ctrl: true }, () => { called = true; });
  s.handle({ key: 'z', ctrlKey: true, shiftKey: false, altKey: false });
  assert(called);
});

test('Ctrl+Shift+Z (Redo) 구분', () => {
  const s = new Shortcuts();
  let undoCalled = false, redoCalled = false;
  s.bind('z', { ctrl: true },             () => { undoCalled = true; });
  s.bind('z', { ctrl: true, shift: true }, () => { redoCalled = true; });
  s.handle({ key: 'z', ctrlKey: true, shiftKey: true,  altKey: false });
  assert(!undoCalled, 'undo 실행 안됨');
  assert(redoCalled,  'redo 실행');
});

test('countBindings 정확', () => {
  const s = new Shortcuts();
  s.bind('a', { ctrl: true }, () => {});
  s.bind('a', { ctrl: true }, () => {});
  assertEqual(s.countBindings('a', { ctrl: true }), 2);
});

test('clear 후 단축키 동작 안함', () => {
  const s = new Shortcuts();
  let called = false;
  s.bind('delete', {}, () => { called = true; });
  s.clear();
  s.handle({ key: 'delete', ctrlKey: false, shiftKey: false, altKey: false });
  assert(!called);
});

// ── 5. createDefaultShortcuts ────────────────────────────────
console.log('\n5. createDefaultShortcuts()');

test('기본 단축키 세트 생성', () => {
  const calls = {};
  const s = createDefaultShortcuts({
    undo:          () => { calls.undo = true; },
    redo:          () => { calls.redo = true; },
    deleteSelected:() => { calls.del  = true; },
    selectAll:     () => { calls.all  = true; },
    escape:        () => { calls.esc  = true; },
    duplicate:     () => { calls.dup  = true; },
  });

  s.handle({ key: 'z',         ctrlKey: true,  shiftKey: false, altKey: false });
  s.handle({ key: 'z',         ctrlKey: true,  shiftKey: true,  altKey: false });
  s.handle({ key: 'delete',    ctrlKey: false, shiftKey: false, altKey: false });
  s.handle({ key: 'a',         ctrlKey: true,  shiftKey: false, altKey: false });
  s.handle({ key: 'escape',    ctrlKey: false, shiftKey: false, altKey: false });
  s.handle({ key: 'd',         ctrlKey: true,  shiftKey: false, altKey: false });

  assert(calls.undo, 'undo 호출');
  assert(calls.redo, 'redo 호출');
  assert(calls.del,  'delete 호출');
  assert(calls.all,  'selectAll 호출');
  assert(calls.esc,  'escape 호출');
  assert(calls.dup,  'duplicate 호출');
});

test('Ctrl+Y도 redo 동작', () => {
  let called = false;
  const s = createDefaultShortcuts({ redo: () => { called = true; } });
  s.handle({ key: 'y', ctrlKey: true, shiftKey: false, altKey: false });
  assert(called);
});

test('Backspace도 delete 동작', () => {
  let called = false;
  const s = createDefaultShortcuts({ deleteSelected: () => { called = true; } });
  s.handle({ key: 'backspace', ctrlKey: false, shiftKey: false, altKey: false });
  assert(called);
});

// ── 결과 ─────────────────────────────────────────────────────
console.log(`\n결과: ${passed} passed, ${failed} failed / ${passed + failed} total`);
if (errors.length > 0) {
  console.log('\n실패 목록:');
  errors.forEach(e => console.log(`  ❌ ${e.name}: ${e.error}`));
}
process.exit(failed > 0 ? 1 : 0);

