_redrawAll() {
  for (const w of this.wires.values()) this._drawWire(w);
}

_portPos(nodeId, portIdx, isOutput) {
  const nv = this.nodes.get(nodeId);
  if (!nv) return {x:0,y:0};
  const portEls = [...nv.el.querySelectorAll('.fw-port')];
  const t = portEls.find(p => +p.dataset.portIdx===portIdx && p.dataset.isOutput===(isOutput?'1':'0'));
  if (!t) return { x: nv.x+(isOutput?nv.width:0), y: nv.y+40 };
  const cr = this.wrap.getBoundingClientRect();
  const pr = t.getBoundingClientRect();
  return {
    x: (pr.left+pr.width/2 - cr.left - this.viewport.x) / this.viewport.scale,
    y: (pr.top+pr.height/2 - cr.top - this.viewport.y) / this.viewport.scale,
  };
}

_bez(x1,y1,x2,y2) {
  const dx = Math.abs(x2-x1)*0.6+40;
  return `M ${x1} ${y1} C ${x1+dx} ${y1}, ${x2-dx} ${y2}, ${x2} ${y2}`;
}

