/**
 * FreeLang StdLib — String 모듈
 * 문자열: 변환, 포맷, 이스케이프, 거리, 템플릿
 */
'use strict';

const string = {
  name: 'std:string',
  version: '1.0.0',

  // ── 기본 변환 ─────────────────────────────────────────────
  upper:      s => String(s).toUpperCase(),
  lower:      s => String(s).toLowerCase(),
  capitalize: s => { const v = String(s); return v.charAt(0).toUpperCase() + v.slice(1).toLowerCase(); },
  title:      s => String(s).replace(/\w\S*/g, t => t.charAt(0).toUpperCase() + t.slice(1).toLowerCase()),
  camelCase:  s => String(s).replace(/[-_\s]+(.)?/g, (_, c) => c ? c.toUpperCase() : '').replace(/^(.)/, c => c.toLowerCase()),
  pascalCase: s => { const c = string.camelCase(s); return c.charAt(0).toUpperCase() + c.slice(1); },
  snakeCase:  s => String(s).replace(/([a-z])([A-Z])/g, '$1_$2').replace(/[-\s]+/g,'_').toLowerCase(),
  kebabCase:  s => String(s).replace(/([a-z])([A-Z])/g, '$1-$2').replace(/[_\s]+/g,'-').toLowerCase(),

  // ── 공백 처리 ─────────────────────────────────────────────
  trim:    s => String(s).trim(),
  ltrim:   s => String(s).trimStart(),
  rtrim:   s => String(s).trimEnd(),
  compact: s => String(s).replace(/\s+/g, ' ').trim(),

  // ── 패딩 / 자르기 ─────────────────────────────────────────
  padStart:  (s, n, fill = ' ') => String(s).padStart(n, fill),
  padEnd:    (s, n, fill = ' ') => String(s).padEnd(n, fill),
  center:    (s, n, fill = ' ') => {
    const v = String(s), gap = Math.max(0, n - v.length);
    const lo = Math.floor(gap / 2), hi = gap - lo;
    return fill.repeat(lo) + v + fill.repeat(hi);
  },
  truncate:  (s, n, suffix = '…') => {
    const v = String(s);
    return v.length <= n ? v : v.slice(0, n - suffix.length) + suffix;
  },
