/**
 * FreeLang StdLib — Functional 모듈
 * 함수형 프로그래밍 유틸: compose, pipe, curry, memoize, 제어흐름
 */
'use strict';

const functional = {
  name: 'std:functional',
  version: '1.0.0',

  // ── 함수 합성 ─────────────────────────────────────────────
  /** compose(f, g, h)(x) === f(g(h(x))) — 오른쪽→왼쪽 */
  compose: (...fns) => x => fns.reduceRight((v, f) => f(v), x),

  /** pipe(f, g, h)(x) === h(g(f(x))) — 왼쪽→오른쪽 */
  pipe: (...fns) => x => fns.reduce((v, f) => f(v), x),

  /** 비동기 pipe */
  pipeAsync: (...fns) => async x => {
    let v = x;
    for (const f of fns) v = await f(v);
    return v;
  },

  // ── 커링 / 부분 적용 ──────────────────────────────────────
  /**
   * curry(f) — 모든 인자를 하나씩 받는 커리 함수
   * curry((a,b,c) => a+b+c)(1)(2)(3) === 6
   */
  curry: fn => {
    const arity = fn.length;
    function curried(...args) {
      if (args.length >= arity) return fn(...args);
      return (...more) => curried(...args, ...more);
    }
    return curried;
  },

  /**
   * partial(f, ...args) — 일부 인자를 미리 적용
   */
  partial: (fn, ...partial) => (...args) => fn(...partial, ...args),
  partialRight: (fn, ...partial) => (...args) => fn(...args, ...partial),

  // ── 메모이제이션 ──────────────────────────────────────────
  /**
   * memoize(fn, resolver?) — 결과 캐싱
   * resolver: 캐시 키 생성 함수 (기본: 첫 번째 인자)
   */
  memoize: (fn, resolver) => {
    const cache = new Map();
    return function memoized(...args) {
      const key = resolver ? resolver(...args) : args[0];
      if (cache.has(key)) return cache.get(key);
      const result = fn.apply(this, args);
      cache.set(key, result);
      return result;
    };
  },

  // ── 제어 흐름 ─────────────────────────────────────────────
  /** once(fn) — 최초 1회만 실행 */
  once: fn => {
    let called = false, result;
    return (...args) => { if (!called) { called = true; result = fn(...args); } return result; };
  },

  /** before(n, fn) — n번 이하만 실행 */
  before: (n, fn) => {
    let count = 0, result;
    return (...args) => { if (++count <= n) result = fn(...args); return result; };
  },

  /** after(n, fn) — n번 이후부터 실행 */
  after: (n, fn) => {
    let count = 0;
    return (...args) => { if (++count >= n) return fn(...args); };
  },

  /** negate(fn) — 결과를 반전 */
  negate: fn => (...args) => !fn(...args),

  /** identity(x) — 그대로 반환 */
  identity: x => x,

  /** constant(x) — x를 항상 반환하는 함수 생성 */
  constant: x => () => x,

  /** noop — 아무것도 안 함 */
  noop: () => {},

  // ── 디바운스 / 스로틀 ─────────────────────────────────────
  /**
   * debounce(fn, ms) — 마지막 호출 후 ms가 지나면 실행
   */
  debounce: (fn, ms) => {
    let timer = null;
    return function(...args) {
      clearTimeout(timer);
      timer = setTimeout(() => fn.apply(this, args), ms);
    };
  },

  /**
   * throttle(fn, ms) — ms마다 최대 1번 실행
   */
  throttle: (fn, ms) => {
    let last = 0;
    return function(...args) {
      const now = Date.now();
      if (now - last >= ms) { last = now; return fn.apply(this, args); }
    };
  },

  // ── 재시도 / 지연 ─────────────────────────────────────────
  /**
   * retry(fn, times, delay) — 최대 times번 재시도
   */
  retry: async (fn, times = 3, delay = 0) => {
    let lastErr;
    for (let i = 0; i < times; i++) {
      try { return await fn(); }
      catch (e) {
        lastErr = e;
        if (i < times - 1 && delay > 0) await new Promise(r => setTimeout(r, delay));
      }
    }
    throw lastErr;
  },

  /** delay(ms) — Promise 지연 */
  delay: ms => new Promise(r => setTimeout(r, ms)),

  /**
   * attempt(fn, ...args) — 에러 발생 시 Error 반환 (throw 안 함)
   */
  attempt: (fn, ...args) => {
    try { return fn(...args); }
    catch (e) { return e instanceof Error ? e : new Error(String(e)); }
  },

  // ── 조건부 ────────────────────────────────────────────────
  /** ifElse(pred, onTrue, onFalse)(x) */
  ifElse: (pred, onTrue, onFalse) => x => pred(x) ? onTrue(x) : onFalse(x),

  /** cond([[pred,fn], ...]) — 첫 번째 일치 분기 실행 */
  cond: pairs => x => {
    for (const [pred, fn] of pairs) { if (pred(x)) return fn(x); }
  },

  /** tap(fn)(x) — 사이드 이펙트 후 x 그대로 반환 (파이프 디버깅용) */
  tap: fn => x => { fn(x); return x; },
};

module.exports = functional;

