/**
 * FreeLang StdLib — Datetime 모듈
 * 날짜/시간 파싱, 포맷, 연산, 비교
 * 외부 의존성 없음 (순수 Date API)
 */
'use strict';

const datetime = {
  name: 'std:datetime',
  version: '1.0.0',

  // ── 생성 ──────────────────────────────────────────────────
  now:       () => new Date(),
  fromTs:    ts => new Date(ts),
  fromStr:   s  => new Date(s),
  of: (year, month = 1, day = 1, h = 0, m = 0, s = 0) =>
    new Date(year, month - 1, day, h, m, s),

  // ── 타임스탬프 ────────────────────────────────────────────
  toTs:      d => d.getTime(),
  nowTs:     () => Date.now(),
  toIso:     d => d.toISOString(),
  toLocal:   d => d.toLocaleString(),

  // ── 포맷 ──────────────────────────────────────────────────
  /**
   * format(date, pattern)
   * 패턴: YYYY 연도, MM 월, DD 일, HH 시, mm 분, ss 초, SSS 밀리초
   */
  format: (d, pattern) => {
    const pad = (v, n = 2) => String(v).padStart(n, '0');
    return String(pattern)
      .replace('YYYY', d.getFullYear())
      .replace('YY',   String(d.getFullYear()).slice(-2))
      .replace('MM',   pad(d.getMonth() + 1))
      .replace('DD',   pad(d.getDate()))
      .replace('HH',   pad(d.getHours()))
      .replace('mm',   pad(d.getMinutes()))
      .replace('ss',   pad(d.getSeconds()))
      .replace('SSS',  pad(d.getMilliseconds(), 3))
      .replace('ddd',  ['일','월','화','수','목','금','토'][d.getDay()])
      .replace('dddd', ['일요일','월요일','화요일','수요일','목요일','금요일','토요일'][d.getDay()]);
  },

  // ── 덧셈 / 뺄셈 ───────────────────────────────────────────
  addMs:      (d, ms)  => new Date(d.getTime() + ms),
  addSeconds: (d, n)   => datetime.addMs(d, n * 1000),
  addMinutes: (d, n)   => datetime.addMs(d, n * 60_000),
  addHours:   (d, n)   => datetime.addMs(d, n * 3_600_000),
  addDays:    (d, n)   => { const r = new Date(d); r.setDate(r.getDate() + n); return r; },
  addMonths:  (d, n)   => { const r = new Date(d); r.setMonth(r.getMonth() + n); return r; },
  addYears:   (d, n)   => { const r = new Date(d); r.setFullYear(r.getFullYear() + n); return r; },
  subDays:    (d, n)   => datetime.addDays(d, -n),
  subMonths:  (d, n)   => datetime.addMonths(d, -n),
  subYears:   (d, n)   => datetime.addYears(d, -n),

  // ── 차이 계산 ─────────────────────────────────────────────
  diffMs:      (a, b) => Math.abs(a.getTime() - b.getTime()),
  diffSeconds: (a, b) => Math.floor(datetime.diffMs(a, b) / 1000),
  diffMinutes: (a, b) => Math.floor(datetime.diffMs(a, b) / 60_000),
  diffHours:   (a, b) => Math.floor(datetime.diffMs(a, b) / 3_600_000),
  diffDays:    (a, b) => Math.floor(datetime.diffMs(a, b) / 86_400_000),
  diffMonths:  (a, b) => {
    const ya = a.getFullYear(), yb = b.getFullYear();
    return Math.abs((ya - yb) * 12 + (a.getMonth() - b.getMonth()));
  },
  diffYears:   (a, b) => Math.abs(a.getFullYear() - b.getFullYear()),

  // ── 비교 ──────────────────────────────────────────────────
  isBefore:   (a, b) => a.getTime() < b.getTime(),
  isAfter:    (a, b) => a.getTime() > b.getTime(),
  isEqual:    (a, b) => a.getTime() === b.getTime(),
  isBetween:  (d, from, to) => d.getTime() >= from.getTime() && d.getTime() <= to.getTime(),
  isSameDay:  (a, b) => a.getFullYear()===b.getFullYear() && a.getMonth()===b.getMonth() && a.getDate()===b.getDate(),
  isSameMonth:(a, b) => a.getFullYear()===b.getFullYear() && a.getMonth()===b.getMonth(),
  isSameYear: (a, b) => a.getFullYear()===b.getFullYear(),

  // ── 경계 ──────────────────────────────────────────────────
  startOfDay:   d => new Date(d.getFullYear(), d.getMonth(), d.getDate()),
  endOfDay:     d => new Date(d.getFullYear(), d.getMonth(), d.getDate(), 23, 59, 59, 999),
  startOfMonth: d => new Date(d.getFullYear(), d.getMonth(), 1),
  endOfMonth:   d => new Date(d.getFullYear(), d.getMonth() + 1, 0, 23, 59, 59, 999),
  startOfYear:  d => new Date(d.getFullYear(), 0, 1),
  endOfYear:    d => new Date(d.getFullYear(), 11, 31, 23, 59, 59, 999),

  // ── 조회 ──────────────────────────────────────────────────
  year:       d => d.getFullYear(),
  month:      d => d.getMonth() + 1,
  day:        d => d.getDate(),
  hour:       d => d.getHours(),
  minute:     d => d.getMinutes(),
  second:     d => d.getSeconds(),
  dayOfWeek:  d => d.getDay(),           // 0=일, 6=토
  dayOfYear:  d => {
    const start = new Date(d.getFullYear(), 0, 0);
    return Math.floor((d - start) / 86_400_000);
  },
  isLeapYear: d => {
    const y = d.getFullYear();
    return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
  },
  daysInMonth: d => new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate(),
  isWeekend:   d => d.getDay() === 0 || d.getDay() === 6,
  isWeekday:   d => !datetime.isWeekend(d),

  // ── 상대 시간 표시 ────────────────────────────────────────
  /**
   * fromNow(date) — "3일 전", "방금 전", "2시간 후"
   */
  fromNow: d => {
    const diff = Date.now() - d.getTime();
    const abs  = Math.abs(diff);
    const past = diff > 0;
    if (abs < 60_000)          return '방금 전';
    if (abs < 3_600_000)       return `${Math.floor(abs/60_000)}분 ${past?'전':'후'}`;
    if (abs < 86_400_000)      return `${Math.floor(abs/3_600_000)}시간 ${past?'전':'후'}`;
    if (abs < 30*86_400_000)   return `${Math.floor(abs/86_400_000)}일 ${past?'전':'후'}`;
    if (abs < 365*86_400_000)  return `${Math.floor(abs/30/86_400_000)}개월 ${past?'전':'후'}`;
    return `${Math.floor(abs/365/86_400_000)}년 ${past?'전':'후'}`;
  },
};

module.exports = datetime;

