  isSameMonth:(a, b) => a.getFullYear()===b.getFullYear() && a.getMonth()===b.getMonth(),
  isSameYear: (a, b) => a.getFullYear()===b.getFullYear(),

  // ── 경계 ──────────────────────────────────────────────────
  startOfDay:   d => new Date(d.getFullYear(), d.getMonth(), d.getDate()),
  endOfDay:     d => new Date(d.getFullYear(), d.getMonth(), d.getDate(), 23, 59, 59, 999),
  startOfMonth: d => new Date(d.getFullYear(), d.getMonth(), 1),
  endOfMonth:   d => new Date(d.getFullYear(), d.getMonth() + 1, 0, 23, 59, 59, 999),
  startOfYear:  d => new Date(d.getFullYear(), 0, 1),
  endOfYear:    d => new Date(d.getFullYear(), 11, 31, 23, 59, 59, 999),

  // ── 조회 ──────────────────────────────────────────────────
  year:       d => d.getFullYear(),
  month:      d => d.getMonth() + 1,
  day:        d => d.getDate(),
  hour:       d => d.getHours(),
  minute:     d => d.getMinutes(),
  second:     d => d.getSeconds(),
  dayOfWeek:  d => d.getDay(),           // 0=일, 6=토
  dayOfYear:  d => {
    const start = new Date(d.getFullYear(), 0, 0);
    return Math.floor((d - start) / 86_400_000);
  },
  isLeapYear: d => {
    const y = d.getFullYear();
    return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
  },
  daysInMonth: d => new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate(),
  isWeekend:   d => d.getDay() === 0 || d.getDay() === 6,
  isWeekday:   d => !datetime.isWeekend(d),

  // ── 상대 시간 표시 ────────────────────────────────────────
  /**
   * fromNow(date) — "3일 전", "방금 전", "2시간 후"
   */
  fromNow: d => {
    const diff = Date.now() - d.getTime();
    const abs  = Math.abs(diff);
    const past = diff > 0;
    if (abs < 60_000)          return '방금 전';
    if (abs < 3_600_000)       return `${Math.floor(abs/60_000)}분 ${past?'전':'후'}`;
    if (abs < 86_400_000)      return `${Math.floor(abs/3_600_000)}시간 ${past?'전':'후'}`;
    if (abs < 30*86_400_000)   return `${Math.floor(abs/86_400_000)}일 ${past?'전':'후'}`;
    if (abs < 365*86_400_000)  return `${Math.floor(abs/30/86_400_000)}개월 ${past?'전':'후'}`;
    return `${Math.floor(abs/365/86_400_000)}년 ${past?'전':'후'}`;
  },
};

module.exports = datetime;

